enum LilApp {
  static let name = "lil art"
  static let repo: String? = nil
  /// Skins offered in Settings → Оформление, and the one used until the user picks.
  static let skins: [LilSkin] = [.studio, .brutal, .riso, .te]
  static let defaultSkin = LilSkin.studio
  /// nil: follow the system until the user picks.
  static let defaultMode: LilMode? = nil
  /// Keep the photo surround (P.stage) neutral grey in every skin.
  static let neutralStage = false
}
